function countSubarrays(nums) {
  let total = 0;
  let runLength = 1;

  for (let i = 1; i <= nums.length; i++) {
    if (i < nums.length && nums[i] > nums[i - 1]) {
      runLength++;
    } else {
      total += runLength * (runLength + 1) / 2;
      runLength = 1;
    }
  }
  return total;
}

