function countSubarrays(nums) {
  let count = 0;
  for (let start = 0; start < nums.length; start++) {
    for (let end = start; end < nums.length; end++) {
      let increasing = true;
      for (let k = start + 1; k <= end; k++) if (nums[k] <= nums[k - 1]) increasing = false;
