  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 9);
  const style = rand();
  const nums = [];
  if (style < 0.3) {
    // Long climbing stretches broken by occasional drops or repeats.
    let value = 1 + Math.floor(rand() * 5);
    for (let i = 0; i < n; i++) {
      if (rand() < (size === 'large' ? 0.01 : 0.2)) value = Math.max(1, value - Math.floor(rand() * 4));
      else value += 1 + Math.floor(rand() * 3);
      nums.push(Math.min(value, 1000000));
    }
  } else {
    const span = size === 'large' ? 1000000 : (style < 0.6 ? 3 : 10);
    for (let i = 0; i < n; i++) nums.push(1 + Math.floor(rand() * span));
  }
  return [nums];
}
